import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"DIY Guide","description":"","frontmatter":{},"headers":[],"relativePath":"diyguide.md","filePath":"diyguide.md"}`),a={name:`diyguide.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="diy-guide" tabindex="-1">DIY Guide <a class="header-anchor" href="#diy-guide" aria-label="Permalink to “DIY Guide”">​</a></h1><p>DIY guiden vil dække de forskellige ressourcer og information som du vil få brug for hvis du vil bruge DIY hormonbehandling, men den dækker dog også nogle ting som er gode at vide hvis du er i behandling ved en privat klinik.</p><h2 id="ressourcer" tabindex="-1">Ressourcer <a class="header-anchor" href="#ressourcer" aria-label="Permalink to “Ressourcer”">​</a></h2><p>Der findes mange forskellige hjemmesider og forumer med information om DIY hormonbehandling. En af de største ressourcer er <a href="https://www.reddit.com/r/TransDIY/" target="_blank" rel="noreferrer">r/TransDIY</a>. Deres <a href="https://www.reddit.com/r/TransDIY/wiki/index/" target="_blank" rel="noreferrer">wiki</a> og <a href="https://www.reddit.com/r/TransDIY/wiki/faq/" target="_blank" rel="noreferrer">FAQ</a> har virkelig meget fantastisk information om DIY hormonbehandling og er et godt sted at starte. Hvis reddit siger du skal bekræfte din identitet for at se det, vil jeg anbefale at bruge en VPN eller bruge en reddit frontend som <a href="https://github.com/redlib-org/redlib-instances/blob/main/instances.md" target="_blank" rel="noreferrer">Redlib</a>.</p><p>En anden virkelig god side er <a href="https://diyhrt.info/" target="_blank" rel="noreferrer">diyhrt.info</a>. De har rigtig meget information om DIY hormonbehandling, og jeg vil anbefale at du læser hele deres transfem/transmasc guide hvis du er interesseret i DIY hormonbehandling eller bare hormonbehandling generelt.</p><p><a href="https://transharmreduction.org/" target="_blank" rel="noreferrer">Trans Harm Reduction</a> er en virkelig god side til forskellige ting, men noget af det vigtigste de laver er at teste hormonerne fra forskellige sælgere så vi kan være sikre på, at hormonerne er sikre og effektive.</p><p><a href="https://transfemscience.org/" target="_blank" rel="noreferrer">TransfemScience</a> er endnu en fantastisk side med masser af information om hormonbehandling. Jeg vil højt anbefale at læse deres artikel <a href="https://transfemscience.org/articles/transfem-intro/" target="_blank" rel="noreferrer">An Introduction to Hormone Therapy for Transfeminine People</a> da den har virkelig meget vigtig information som er god at vide hvis man vil starte DIY hormonbehandling.</p><h2 id="sælgere" tabindex="-1">Sælgere <a class="header-anchor" href="#sælgere" aria-label="Permalink to “Sælgere”">​</a></h2><p>For at finde sælgere vil jeg højt anbefale <a href="https://valerie.vg/" target="_blank" rel="noreferrer">valerie.vg</a> og <a href="https://diyhrt.coffee/" target="_blank" rel="noreferrer">diyhrt.coffee</a>. De holder styr på de forskellige sælgere og hvem der har hormoner på lager. Jeg vil også anbefale at holde øje med <a href="https://www.reddit.com/r/TransDIY/" target="_blank" rel="noreferrer">r/TransDIY</a> da folk ofte poster om deres oplevelser med forskellige sælgere.</p><h2 id="blodprøver" tabindex="-1">Blodprøver <a class="header-anchor" href="#blodprøver" aria-label="Permalink to “Blodprøver”">​</a></h2><p>Hvis du vil have hormonbehandling er blodprøver altid meget vigtige. Vi tager som regel blodprøver før vi starter hormonbehandling, og så igen 3 måneder efter vi er startet. Derefter holder vi også øje med vores niveauer hver 6.-12. måned, eller hver gang der er ændringer i vores dosering.</p><p>Som regel før man starter hormonbehandling, vil vi tage de følgende blodprøver:</p><ul><li>Komplet blodtælling (hvide blodlegemer, røde blodlegemer, hæmoglobin, blodplader, hæmatokrit, gennemsnitligt korpuskulært volumen)</li><li>Leverfunktionstests (ALT, AST, ALP, bilirubin)</li><li>Fastende blodsukker</li><li>Urea og elektrolytter/nyrepanel (kreatinin, eGFR, urea, kalium, natrium)</li><li>Lipid-/kolesterolpanel (total kolesterol, triglycerider, HDL, LDL)</li><li>Prolaktin (PRL)</li><li>Testosteron og østradiol (total testosteron og E2)</li></ul><p>Når vi er i gang med hormonbehandling og tager vores opfølgende blodprøver, så tager vi som regel disse blodprøver:</p><ul><li>Leverfunktionsprøver (ALT, AST, ALP, bilirubin)</li><li>Urea og elektrolytter / nyrepanel (kreatinin, eGFR, urea, kalium, natrium)</li><li>Lipider / kolesterolpanel (total kolesterol, triglycerider, HDL, LDL)</li><li>Prolaktin (PRL)</li><li>Testosteron og østradiol (total testosteron og E2)</li></ul><p>Hvis du er på <a href="https://min.medicin.dk/Medicin/Indholdsstoffer/318" target="_blank" rel="noreferrer">cyproteronacetat</a> (ofte Androcur), er det meget vigtigt, at du især holder øje med dine prolaktinniveauer. Cyproteronacetat har en lille chance for at give <a href="https://en.wikipedia.org/wiki/Prolactinoma" target="_blank" rel="noreferrer">prolaktinom</a>, hvilket er en godartet svulst i hypofysen. Det er ikke en almindelig bivirkning af cyproteronacetat, men hvis dine prolaktinniveauer er meget høje, er det vigtigt at tale med din læge.</p><p>Når du skal have taget blodprøver, kan du måske være forvirret over, hvor du skal have taget dem, da din egen læge højst sandsynligt ikke vil tage dem. Den bedste løsning i min oplevelse er at få taget blodprøverne ved <a href="https://ds-vt.dk/" target="_blank" rel="noreferrer">Dansk Sundhedsteam</a>. Man kan bestille blodprøver ved dem, hvorefter de så lægger dem ind på systemet så du kan bestille tid til blodprøvetagning ved et hospital i din region. Det er en super mulighed fordi du ikke behøver at tage ind på deres klinik men kan i stedet få taget dem på et hospital i nærheden af dig. Efter du har fået taget dem, bliver blodprøverne sendt til deres laboratorium. Når de har gjort deres arbejde, sender de dig resultaterne digitalt.</p><p>Det kan være lidt dyrt, men i min erfaring er det den billigste mulighed du har. Hvis du er i behandling ved Imago, kan du dog nævne det for dem, og de kan så trække moms fra prisen så du kan spare nogle penge.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};